INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('32ab96aa-8a5b-4d6e-a12f-87488b641f40', '21feff02-016d-46e2-bb9d-c27495133b1b', '71. óra: Egyenes arányosság', 'Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "fdd133ed-9b3f-4394-bcf5-a064a5e5367c", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "948866be-a788-44cf-a0d7-0a8620babe3a", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "5486ab40-ec3e-4c4b-8c4f-0a4ca73a20d5", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "fd03684d-09e4-48e5-a4a6-5a3f79aa66c4", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "71a8b1c5-a9fc-447c-b9ab-8ab6ecf083fc", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "63e31160-b6f2-4cee-a137-f92e9888a4db", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "a69d522a-54bf-4406-a562-a9d1ab2824d3", "text": "Igaz", "isCorrect": true}, {"id": "b9664c06-9ce5-43d8-a335-fd5e2eb788b9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a9848a83-32a4-4ee3-b825-711dbd1c6d1f", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "aae77ea8-7f30-46d3-b98a-45052523aaae", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "4935d363-74f7-487a-8fa2-7f4682111bce", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "df1d897b-8bd4-4815-8fa6-bd88f556bbbc", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "da4ed849-1ddd-4689-89fd-3d07eba5527c", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "de528f21-7581-4458-ae1d-d364755b900b", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "81647240-b2df-4d1b-81c2-de3cfb91212e", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "f20ff7c2-d9f7-4797-b276-f8755aeadcb6", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "85c5bead-d031-4a2d-9625-3b52bde8fa4f", "text": "Igaz", "isCorrect": true}, {"id": "603a79f8-2c74-4c09-8c92-bb1af0947fa7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ed998f6e-0c08-49e2-93d3-b6d4b3933a5d", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ced9516a-ffed-482c-ac35-904a878b3205', '21feff02-016d-46e2-bb9d-c27495133b1b', '72. óra: Egyenes arányosság grafikonja', 'Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d3705ae7-82aa-4179-94de-de3167060148", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "9a297eb6-e86b-48ea-85ba-ef64b109512d", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "4934f25b-5c17-46bf-965c-cb41ddae22d4", "text": "Parabola", "isCorrect": false}, {"id": "02ea9802-09ba-452b-b6c2-db2489e3915b", "text": "Körvonal", "isCorrect": false}, {"id": "7abc59d6-aa54-4770-8ec6-6575bc2409e3", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "f0d11ab5-3974-4f9e-bc13-6fbd2a1ceb94", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "1d9674db-30b8-40e5-ab9f-0bd206abcb65", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "b47ceff9-157c-422b-80c5-f21df69db17d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "04edbf00-419c-469c-ad01-d5a82be54149", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "979581e0-1e81-459a-8cf1-6d97b404ad3a", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "38826147-0ddb-4318-906b-d0a6e3d6b2aa", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "ba099911-95b1-459d-8d4d-85d3e9771a61", "text": "Igaz", "isCorrect": true}, {"id": "e160b10c-b7b5-4be4-9870-7aa9293eac71", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0b9ea4f1-5d78-4dc0-9cc9-3e8bfe269870", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "2fee0c3c-a7bf-4b96-9891-f6258ef7a28d", "text": "Igaz", "isCorrect": true}, {"id": "03233208-504d-4f9c-984c-fccf1bd98ae6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cab60d43-3254-4eae-a1fa-f1d76799cced", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "d7817c94-8dca-4073-84b3-f8a03ca2bec1", "text": "Igaz", "isCorrect": true}, {"id": "925e2999-1a6f-4065-84da-2fcdda33812c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('312be2a0-d367-4a04-8085-ea844b3f92b2', '21feff02-016d-46e2-bb9d-c27495133b1b', '73. óra: Gyakorlóóra', 'Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "c648075c-554c-428f-9e72-11f72e2ec0c4", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "eeb12248-84fb-4e51-8c11-bae07d486537", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "bb8b89a2-0c85-4afe-8baf-25873e4626bb", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "c58ef938-8aef-4a4e-9459-accbab55a567", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "f2fd88bc-5e8b-4b71-bb88-fe9c76bc2cfe", "text": "Igaz", "isCorrect": true}, {"id": "cceb102b-1925-4f82-84b0-94a31a7c6392", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e8ea4af8-3dac-4d4e-93f8-ee683265083f", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "fe20bacf-37e1-4cd6-8308-5be896c7eaa5", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "e8dd76f6-7c0d-4da4-b265-c82dd8e2c9d7", "text": "Igaz", "isCorrect": true}, {"id": "dcfe2907-b668-4ccf-8a5a-4162b9311c11", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d39661a0-6ae7-4e46-8c3a-8a0dce98ea2a", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c531e6ff-7d13-4afe-a5a2-1c55fa1cf306', '21feff02-016d-46e2-bb9d-c27495133b1b', '74. óra: Matematikai játékok', 'Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "9618e5be-f188-4c48-ba80-a6db7e72c505", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "19588113-80b4-4ed8-ab1f-8ae1edefe201", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "3ebb9724-37d0-4c92-85f5-0445e6911984", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "3e36de42-f904-499a-95ce-095f60f9c86d", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "fd3bf751-9d66-4bb7-b42f-2c592c828e76", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "76eb7f0e-9251-4bc2-bc68-c3f4ac42e371", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "a4fc2ac7-b298-4b88-abce-6de13eab86f7", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "37a2c056-8830-44c9-83a3-bec876e8316e", "text": "Igaz", "isCorrect": true}, {"id": "e02a556b-1732-4a97-a928-b46ace4d355e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4673fc34-6ed9-4b0c-a9aa-2ce34e007d6d", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "fa964d49-31f5-449b-8e6e-9b8caaebfdd1", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "f1eb5cd8-5977-468f-9536-582c0419f544", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "30508a9b-cd3c-4c6e-9be2-5e4bc2e9e686", "text": "Igaz", "isCorrect": true}, {"id": "a6b4833e-fe19-41f7-84ba-d62ab6a8591d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5b4816ef-f362-4cfc-9b7b-482877a47e45", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "378856b5-ff2b-410c-b169-aa4495be10ae", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "12ddc190-32d5-4ee9-a1f5-ec55cfe3d22f", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "65443464-26df-4435-829b-2f960de783c8", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "b725a120-fdae-4352-b5d9-b76e53d7ad58", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4602afc7-89c6-493b-8c81-b25ea8604b61', '21feff02-016d-46e2-bb9d-c27495133b1b', '75. óra: Szabályok, megfeleltetések', 'Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "ccbe9eb9-aa3c-4756-8929-a11a66d70f3a", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "eba4e2ad-1e49-42a3-b40e-d6c2efd0ac83", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "640fe86c-9fc5-4a51-ac8b-c8841352d10c", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "299416c3-a8a5-4109-b3c9-1f8e7d5a1db9", "text": "Igaz", "isCorrect": true}, {"id": "6006f314-d82b-4bac-8b06-39dc1324683b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "213d9431-024c-4698-8782-c7290dd14ba4", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "074454c5-940b-4d72-ab9f-d5a44c0b3fdb", "text": "Melyik sorozat szabálya a ''Hozzáadás 5-tel''?", "type": "multiple-choice", "options": [{"id": "87cec35b-f09b-4971-a101-a20bace5f4a3", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "e759b7fc-df1d-4bf6-bc78-ee19d8e92036", "text": "5, 25, 125", "isCorrect": false}, {"id": "b214f191-0cc9-45a9-b7a2-716a419778e0", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "04443760-713c-443a-949c-57e2d86e5c00", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "20940cb5-a6b2-48f2-b0dc-6063dc5c743f", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "ea4ab494-e104-4aa7-aae3-c6c7555c588f", "text": "Igaz", "isCorrect": true}, {"id": "fb9354df-79f3-42a1-b7f6-0b29a810829b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d964df97-a9ff-4ed6-b1ac-1d3dfe1cc280", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('53b9abd9-216a-48b1-a29f-a29000252e4f', '21feff02-016d-46e2-bb9d-c27495133b1b', '76. óra: Gyakorlóóra', 'Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8129a08b-4117-42f5-81bc-3466145837ce", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "e6d20422-81ca-4b0e-b211-52def84d8f80", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "cf6541e0-e51c-45ec-9254-4ab652448bc8", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "36b5b407-8889-4720-abfe-976ae78df80a", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "c8c1901a-3785-4bd2-ba18-9b03c5e4b8f6", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "f9847d43-122a-4601-9a50-719bda927333", "text": "Igaz", "isCorrect": true}, {"id": "1ff71c6f-76e1-41d7-9b7d-55008c116fd5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "de212464-497d-470f-a913-3a18e0ac197b", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "06796113-7604-4c87-ac02-518af86e8fee", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "a5773a2b-a41d-456d-bf18-b876fe39b295", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "0ecca3c1-0fa3-4d7d-914c-f65eb6ea5a2b", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "3ec28c38-0960-4353-9f93-d1c99785bab2", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "99c32894-ceb7-420a-a42a-bd526c2440a2", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "061a513c-7226-49b0-90a5-36ca9c004809", "text": "Igaz", "isCorrect": true}, {"id": "5e1d28bc-fb41-4623-9fd9-488e7c6bfcf4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6de1ae48-b076-41d0-80a9-2a1c258baa4c', '21feff02-016d-46e2-bb9d-c27495133b1b', '77. óra: Törtrész', 'Törtrész kiszámítása és kapcsolata az egyenes arányossággal.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "a9976f0c-1839-4459-a6f5-103f8848c5bc", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "4fff731f-a0c1-44f9-a1db-155bf35b8b21", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "a08758f3-fc9a-47d1-bcb7-0255315e1dde", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "14f631ab-effe-4610-abc0-361c47d9c390", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "ee272b80-8b56-4ff9-be8c-4456bcefe5ef", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "af52718f-7384-4c6b-acfc-68cef6c48c97", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "2ca8c6c0-9311-4d11-ab89-4da344222ccf", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "862205e4-4808-4b8e-b65f-a55df944b4a9", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "bdc157b2-1f90-4b6d-8f49-efe7ece1c81c", "text": "Igaz", "isCorrect": true}, {"id": "ddd6d25f-f202-46cd-9a86-db09da322e76", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d94e0031-fa1f-4991-90df-ca13b173ca2f", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "b49333d3-e936-4c90-b6f2-f3a29bae7617", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b5e8dec2-ff9f-4368-a53c-5978b36ffb48", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('59140caf-d76b-4ad6-9202-4cc7977bfebe', '21feff02-016d-46e2-bb9d-c27495133b1b', '78. óra: Feladatmegoldás', 'Összetett feladatok megoldása törtrész kiszámításával.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "979dc700-0ecd-4219-bf4a-ec40ac251eaa", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "4e3db1b6-fcdc-4458-b37a-30be3c75ed64", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "4de7ea92-fd1b-4191-ae8b-650e62543fef", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "600c21d7-406c-4b3c-89db-73b52cb3c02c", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "8058fd73-fdf8-496b-89d8-964ab400d35a", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "3d70fb1e-2601-45d2-9c91-bb79f576bb3d", "text": "Igaz", "isCorrect": true}, {"id": "d69b9fdd-09f3-4933-bf0f-374227c9f38f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9dbe07d5-8eee-4852-b8ea-4c3136c6d871", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "2c8f1c07-ff5c-4618-ad35-8b3c874060a7", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "eeb37f2f-c845-4e98-972b-8f3c00636b8c", "text": "Igaz", "isCorrect": true}, {"id": "35f3a947-deaa-40c8-b27b-a4c15240b8cd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('04e8e430-5aee-4bfb-8b22-18fdb0f86ee8', '21feff02-016d-46e2-bb9d-c27495133b1b', '79. óra: Számonkérés', 'Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "56664dcb-01fa-445e-993c-9ce069224a04", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "dd2df533-70e5-4430-81ea-537f7bf7bf12", "text": "1 : 3", "isCorrect": true}, {"id": "e8077a12-0f69-4e7e-a969-4d204c1a3561", "text": "1 : 2", "isCorrect": false}, {"id": "88dacfdd-b650-4532-b4b4-d763133e2cee", "text": "3 : 1", "isCorrect": false}, {"id": "c1ac51de-01f4-4e90-8b75-7bf2b0a3c44f", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "7d0e6fff-46b2-4ae9-8975-238cd385cd2d", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "0922c3fd-5d7e-4f7b-869e-e3e49ee50161", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "322bdb1a-1bd5-46f9-a80a-ec51023afc8e", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "8843cdd7-fa11-46dc-8a06-6ed37a96b162", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "35d45a5e-e977-4de3-a94c-3efe2208d5d4", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "33805dff-6676-499c-a57e-c8d650892948", "text": "Igaz", "isCorrect": true}, {"id": "ff2839d1-5c6f-427d-b74a-6d3b4168deeb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bd7fb701-e177-4e1b-8a37-c8027e79fbcd", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "348b92a6-e231-491f-8180-771998e6fe83", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "6a93026a-72a0-4a68-8d61-e9ae4ad06ba5", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "bbc44dd6-414a-4790-9c65-3c6655a6926e", "text": "Igaz", "isCorrect": true}, {"id": "b97df022-727c-450d-b298-c9f53b5ed196", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bd188f36-369a-4cec-a084-483fbec88e1d", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f96cee1c-15dd-4535-a18f-6aa3e3a7ef26', '21feff02-016d-46e2-bb9d-c27495133b1b', '80. óra: Létraverseny I.', 'Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "1c4f84de-0acd-44fc-b068-6c1c8f29710b", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "c5839c35-ff5b-4c5d-9d07-5532d7103ae8", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "3e5e6475-08bd-4e82-87a9-dcbff9bcff01", "text": "1 : 3", "isCorrect": true}, {"id": "a651726d-b348-4ecd-baff-cc3d85d38684", "text": "1 : 5", "isCorrect": false}, {"id": "e883c6c6-413f-4405-8643-21a7ccd46c79", "text": "3 : 1", "isCorrect": false}, {"id": "eca779ca-57a9-47fe-a888-64bbf5b01063", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "815d4001-8395-469c-8ae6-5576b5fa3c15", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "7b97169a-044a-4e67-9e8d-491d4f676f12", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "a5d6942c-c118-49c0-88f5-abd8bd40d5c0", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "d67ac4b5-4d0e-4315-8c0b-630fd763c7ad", "text": "Igaz", "isCorrect": true}, {"id": "7b1467d8-28e0-4dcd-a42b-c9aa23e93f56", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "271fc6cf-84b7-4457-a347-a4dad4fb15dc", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "01bd3ce9-aa26-4298-8be9-54b99d32cde4", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "eae48be6-a0f5-476b-b71b-7c646e29312c", "text": "Igaz", "isCorrect": true}, {"id": "4e5d4c97-ce23-4100-b5d5-72995852fccf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;